/**
 * @name Pickle deserialization with file path injection
 * @description Pickle deserialization from files with user-controlled paths
 * @kind path-problem
 * @problem.severity high
 * @id py/pickle-file-injection
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PickleFileConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is a file path argument to pickle.load or similar
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["load", "Unpickler"]).getACall() and
      // For pickle.load(file), the first arg is the file object
      // For Unpickler(file), the first arg is the file object
      sink = call.getArg(0)
    )
  }
}

module PickleFileFlow = TaintTracking::Global<PickleFileConfig>;
import PickleFileFlow::PathGraph

from PickleFileFlow::PathNode source, PickleFileFlow::PathNode sink
where PickleFileFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle deserialization from user-controlled file $@.", source.getNode(), "input"
